import{I as e,b as t,y as n}from"./vue-Bcr2QcGB.js";import{a as r}from"./app-CLqOxAfT.js";var i=JSON.parse(`{"path":"/tool/note/z08idcd8/","title":"OpenCode Go 订阅接入 Codex | Note","lang":"zh-CN","frontmatter":{"title":"OpenCode Go 订阅接入 Codex","createTime":"2026/09/20 16:08:50","permalink":"/tool/note/z08idcd8/"},"readingTime":{"minutes":9.72,"words":2917},"git":{},"filePathRelative":"tool/note/005.opencode-go-codex-integration.md","headers":[]}`),a={name:`005.opencode-go-codex-integration.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h2 id="概述" tabindex="-1"><a class="header-anchor" href="#概述"><span>概述</span></a></h2><p>Codex 桌面版与它自带的命令行工具共用同一份配置，默认只连 OpenAI 官方账号。本文记录把 <strong>OpenCode Go 订阅</strong>接进 Codex 的完整过程：接口约束、可用模型、最小配置、给模型选择器补上真名，以及实际撞到的报错与处理方式。</p><p>结论先行：可以接入，且完全不需要登录 OpenAI 账号。</p><p>实测环境：Windows 11；Codex 桌面版（商店版 26.915.4065.0）及其自带 CLI 0.155.0-alpha.9.2，另在 CLI 0.155.1 上复现。实测日期 2026-09-20。</p><h2 id="一、codex-只用-responses-这一个接口" tabindex="-1"><a class="header-anchor" href="#一、codex-只用-responses-这一个接口"><span>一、Codex 只用 <code>/responses</code> 这一个接口</span></a></h2><p>Codex 已经不吃 <code>chat/completions</code>，只走 Responses 一条路。</p><table><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>base_url</td><td><code>https://opencode.ai/zen/go/v1</code>（<strong>带 <code>/v1</code></strong>，<code>/responses</code> 由 Codex 自己拼）</td></tr><tr><td>实际请求</td><td><code>POST https://opencode.ai/zen/go/v1/responses</code></td></tr><tr><td>认证</td><td><code>Authorization: Bearer &lt;你的 Go key&gt;</code></td></tr><tr><td>会话头</td><td>Codex 自带，不用手动配</td></tr><tr><td><code>wire_api</code></td><td><strong>只能写 <code>&quot;responses&quot;</code></strong></td></tr></tbody></table><p>有两条硬约束，任何一条写错都会直接卡在启动或认证环节：</p><ol><li><p><code>wire_api = &quot;chat&quot;</code> 已从 Codex 移除（2026-02 起），写了启动即报错：</p><div class="language-text" data-highlighter="shiki" data-ext="text" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-text"><span class="line"><span>Error loading config.toml: wire_api = &quot;chat&quot; is no longer supported.</span></span></code></pre></div></li><li><p>认证必须是 Bearer。Go 网关的 OpenAI 侧不认 <code>x-api-key</code>（那是 <code>/v1/messages</code> 的用法），写错会返回 <code>401 Missing API key</code>。</p></li></ol><h2 id="二、能用的模型" tabindex="-1"><a class="header-anchor" href="#二、能用的模型"><span>二、能用的模型</span></a></h2><p>Go 订阅下的模型并非全部都能被 Codex 调用。扫描方式：对每个模型发一次<strong>带 tools</strong> 的 <code>/responses</code> 请求，模拟 Codex 的真实负载。</p><table><thead><tr><th>状态</th><th>模型</th></tr></thead><tbody><tr><td>可用</td><td><code>deepseek-v4.1-flash</code>、<code>deepseek-v4-flash</code>、<code>deepseek-v4-pro</code>、<code>deepseek-flash</code>、<code>deepseek-v4-flash-vision-exp</code>、<code>gpt-5.6-luna</code></td></tr><tr><td>接口能通但 Codex 用不了</td><td><code>grok-4.6</code>（裸请求 200，走真实 Codex 请求必 <code>422 Upstream request failed</code>，重试 5 次后失败）</td></tr><tr><td>不可用</td><td>GLM 全系（<code>glm-5.3</code> / <code>5.3-flash</code> / <code>5.2</code> / <code>5.1</code> / <code>5</code>）、<code>kimi-k3</code> / <code>k2.7-code</code> / <code>k2.6</code> / <code>k2.5</code>、<code>qwen3.5</code>~<code>3.8</code> 全系、<code>minimax-m3</code> / <code>m2.7</code> / <code>m2.5</code>、<code>hy3</code> / <code>hy3-preview</code> / <code>hy4-preview</code>、<code>mimo-v2-pro</code> / <code>v2-omni</code> / <code>v2.5</code> / <code>v2.5-pro</code>、<code>longcat-2.0</code>、<code>omen-alpha</code>、<code>muse-spark-1.x-contributor</code></td></tr></tbody></table><p>不可用分两类原因：</p><ul><li><code>Model not supported for format openai</code> —— 这些模型在 Go 上只暴露 <code>/chat/completions</code>（或只暴露 <code>/v1/messages</code>），而 Codex 已经不吃 chat。想让它们跑 Codex，必须在本地加一层 <strong>Responses→Chat 转换代理</strong>。</li><li><code>500 Internal server error</code> —— 该模型在 <code>/responses</code> 上没有可用的上游通道。</li></ul><p>上下文长度为 deepseek 全系 <strong>1,048,576（1 MiB）</strong>，官方目录里 <code>context_window</code> / <code>max_context_window</code> 就是 <code>1048576</code>；输出上限 384K（OpenCode 数据页）。</p><h2 id="三、最小可用配置" tabindex="-1"><a class="header-anchor" href="#三、最小可用配置"><span>三、最小可用配置</span></a></h2><p>配置文件：<code>%USERPROFILE%\\.codex\\config.toml</code>，桌面版 app 与 CLI 共用这一份。</p><div class="hint-container warning"><p class="hint-container-title">警告</p><p>顶层键必须写在所有 <code>[表]</code> 之前 TOML 里，表头之后的一切都归那个表。把 <code>[model_providers.opencode-go]</code> 插到 <code>notify</code> 前面，会导致 <code>model</code>、<code>model_provider</code>、<code>notify</code> 全被并进那个表——<strong>不报错，但完全不生效</strong>。<code>codex doctor</code> 会点名：<code>model_providers.opencode-go.notify is ignored</code>。</p></div><p>配置本体是三行顶层键 + 一张 provider 表：</p><div class="language-toml" data-highlighter="shiki" data-ext="toml" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-toml"><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deepseek-v4.1-flash&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model_provider = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;opencode-go&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model_reasoning_effort = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;medium&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model_catalog_json = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;C:\\Users\\&lt;用户名&gt;\\.codex\\go-models.json&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 可选，见第四节</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">notify = [ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;……你原有的内容原样保留……&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ]                          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 顶层键</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># …… app 自己生成的部分（marketplaces / plugins / mcp_servers / windows / projects）全部原样保留 ……</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">model_providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">opencode-go</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;OpenCode Go&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base_url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://opencode.ai/zen/go/v1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">experimental_bearer_token = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sk-...你的Go key&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wire_api = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;responses&quot;</span></span></code></pre></div><p>三个要点：</p><ol><li><p><strong>三行顶层键缺一不可，且都放在文件最前面。</strong> 实测最坑的一种：只加 <code>model_catalog_json</code> 而漏掉或被覆盖了 <code>model_provider</code>，配置不报错，但 provider 掉回内置 <code>openai</code>，请求直接打 <code>wss://api.openai.com/v1/responses</code> 报 401。</p></li><li><p><strong>用 <code>experimental_bearer_token</code>，不要用 <code>env_key</code>。</strong> <code>env_key</code> 需要 <code>setx</code> 设环境变量，而已经在运行的 app、从开始菜单启动的进程继承不到，必须重启才生效；provider 里写 <code>api_key = &quot;...&quot;</code> 则不生效（实测 401）。代价是 key 明文存在配置里，别把文件传 git / 网盘 / 截图。</p><p>Provider 表里三行就能跑通，其中 <code>base_url</code> 一定要带 <code>/v1</code>。</p></li></ol><h3 id="保留官方账号的两全方案-可选" tabindex="-1"><a class="header-anchor" href="#保留官方账号的两全方案-可选"><span>保留官方账号的两全方案（可选）</span></a></h3><p>只想让终端 CLI 走 Go、app 继续走官方账号：<code>config.toml</code> 里<strong>不加</strong> <code>model</code> / <code>model_provider</code>，只加 provider 表，再建一个独立的 profile 文件。</p><p><code>%USERPROFILE%\\.codex\\opencode-go.config.toml</code>：</p><div class="language-toml" data-highlighter="shiki" data-ext="toml" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-toml"><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deepseek-v4.1-flash&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model_provider = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;opencode-go&quot;</span></span></code></pre></div><p>用法：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opencode-go</span></span></code></pre></div><div class="hint-container note"><p class="hint-container-title">笔记</p><p>老写法 <code>[profiles.opencode-go]</code> 表塞进 <code>config.toml</code> 已经失效，实测报错要求改成独立 profile 文件。</p></div><h2 id="四、让模型选择器显示真名" tabindex="-1"><a class="header-anchor" href="#四、让模型选择器显示真名"><span>四、让模型选择器显示真名</span></a></h2><p>装好 provider 后，app 里模型那一栏显示的是「自定义 / 轻度」，看不到 <code>deepseek-v4.1-flash</code>。</p><p>原因是 Codex 内置模型目录里没有 DeepSeek 系，UI 找不到 slug，只能给通用标签，推理档位也回落官方默认（low = 轻度）。这<strong>纯属显示层问题</strong>，路由不受影响。</p><p>修法是给 Codex 一份自定义目录，顶层加一行 <code>model_catalog_json = &#39;&lt;路径&gt;&#39;</code>（TOML 单引号包路径，反斜杠不用转义），目录文件用同一份《Codex 模型目录（仅 OpenCode Go）.json》。</p><table><thead><tr><th>slug</th><th>显示名</th></tr></thead><tbody><tr><td><code>deepseek-v4.1-flash</code></td><td>DeepSeek V4.1 Flash</td></tr><tr><td><code>deepseek-v4-flash</code></td><td>DeepSeek V4 Flash</td></tr><tr><td><code>deepseek-v4-pro</code></td><td>DeepSeek V4 Pro</td></tr><tr><td><code>deepseek-flash</code></td><td>DeepSeek Flash</td></tr><tr><td><code>deepseek-v4-flash-vision-exp</code></td><td>DeepSeek V4 Flash Vision (实验)</td></tr><tr><td><code>gpt-5.6-luna</code></td><td>GPT-5.6 Luna (OpenCode Go)</td></tr></tbody></table><div class="hint-container caution"><p class="hint-container-title">注意</p><p><strong>是替换，不是合并</strong>，自定义目录会把内置目录整体换掉。上面这份不含官方模型，所以选择器里也不会出现它们。想恢复原状，删掉 <code>model_catalog_json</code> 那一行并重启即可，provider 配置不受影响。</p></div><h3 id="目录文件的字段要求" tabindex="-1"><a class="header-anchor" href="#目录文件的字段要求"><span>目录文件的字段要求</span></a></h3><p>首选做法是<strong>直接用 DeepSeek 官方给的 <code>models.json</code> 当模板</strong>——官方在 Codex 接入文档里提供了完整目录（两个条目 <code>deepseek-flash</code> / <code>deepseek-v4-pro</code>），字段和取值都是权威的。这份目录即以它为基底，再补上 Go 订阅里其余可用的模型 id（官方目录只覆盖 DeepSeek 自家两个 id）。</p><p>官方条目的关键值，照抄即可：</p><table><thead><tr><th>字段</th><th>官方值</th></tr></thead><tbody><tr><td><code>shell_type</code></td><td><code>&quot;shell_command&quot;</code></td></tr><tr><td><code>apply_patch_tool_type</code></td><td><code>&quot;freeform&quot;</code></td></tr><tr><td><code>tool_mode</code></td><td><code>null</code></td></tr><tr><td><code>use_responses_lite</code></td><td><code>false</code></td></tr><tr><td><code>prefer_websockets</code></td><td><code>false</code></td></tr><tr><td><code>context_window</code> / <code>max_context_window</code></td><td><code>1048576</code></td></tr><tr><td><code>default_reasoning_level</code></td><td><code>&quot;high&quot;</code></td></tr><tr><td><code>supported_reasoning_levels</code></td><td>官方 <code>low</code> / <code>high</code> / <code>max</code> → 改成 <code>low</code> / <code>medium</code> / <code>high</code>（原因见下）</td></tr><tr><td><code>effective_context_window_percent</code></td><td><code>95</code></td></tr><tr><td><code>truncation_policy</code></td><td><code>{mode:&quot;tokens&quot;, limit:10000}</code></td></tr><tr><td><code>minimal_client_version</code></td><td><code>&quot;0.144.0&quot;</code></td></tr><tr><td><code>base_instructions</code> + <code>model_messages.instructions_template</code></td><td>官方提示词全文，两个都要给</td></tr></tbody></table><p>schema 严格校验，报错会点名缺哪个字段（<code>failed to parse model_catalog_json ... missing field &#39;xxx&#39;</code>）。<strong>必须给 <code>base_instructions</code> 或 <code>model_messages.instructions_template</code></strong>，否则报 <code>missing both base_instructions and model_messages.instructions_template</code>。</p><h3 id="曾经踩的坑-工具调用退化成纯文本" tabindex="-1"><a class="header-anchor" href="#曾经踩的坑-工具调用退化成纯文本"><span>曾经踩的坑：工具调用退化成纯文本</span></a></h3><p>一开始拿 Codex 内置的 GPT 条目当模板，继承了两个值：<code>tool_mode: &quot;code_mode_only&quot;</code> 和 <code>use_responses_lite: true</code>。结果 DeepSeek 的工具调用退化成把 DSML 标记当纯文本吐出：</p><div class="language-text" data-highlighter="shiki" data-ext="text" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-text"><span class="line"><span>&lt;|DSML| invoke name=&quot;apply_patch&quot;&gt;</span></span></code></pre></div><p>文件根本建不出来。换回官方值（<code>tool_mode: null</code>、<code>use_responses_lite: false</code>）后，<code>apply_patch_tool_type: &quot;freeform&quot;</code> 可以正常保留，实测走 apply_patch 建文件成功。问题不在 freeform，而在这两个「代码模式 / 精简响应」开关。</p><p>这份目录相对官方做了两处有意偏离：</p><ol><li><strong><code>supported_reasoning_levels</code> 用 <code>low</code> / <code>medium</code> / <code>high</code>，而不是官方的 <code>low</code> / <code>high</code> / <code>max</code>。</strong> 客户端本身支持的档位是 <code>minimal | low | medium | high | xhigh</code>（官方配置参考里写死），<code>max</code> 渲染不出来——照抄官方会只剩两档（轻度 / 高度）；换成这三档就能显示三档，默认 <code>high</code>。实测三档请求全部 200。</li><li><strong><code>supports_search_tool</code> 一律 <code>false</code></strong>（官方 flash 是 <code>true</code>）。Go 网关不提供托管联网搜索工具，设 true 只会让客户端发一个跑不通的工具。</li></ol><p>顺带一个实测结论：Go 侧对 <code>reasoning.effort</code> 几乎来者不拒——<code>minimal</code> / <code>low</code> / <code>medium</code> / <code>high</code> / <code>xhigh</code> / <code>max</code> / <code>none</code> 全部 200，只有 <code>ultra</code> 会 422。</p><p>不想折腾目录，也可以只控制推理档位（显示层仍是「自定义」）：</p><div class="language-toml" data-highlighter="shiki" data-ext="toml" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-toml"><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model_reasoning_effort = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;medium&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # low / medium / high，实测 Go 网关接受这个参数</span></span></code></pre></div><h2 id="五、验证与生效" tabindex="-1"><a class="header-anchor" href="#五、验证与生效"><span>五、验证与生效</span></a></h2><h3 id="先找到-cli-的真实路径" tabindex="-1"><a class="header-anchor" href="#先找到-cli-的真实路径"><span>先找到 CLI 的真实路径</span></a></h3><p><code>codex</code> 不在 PATH 时，桌面版自带的 CLI 藏在 <code>%LOCALAPPDATA%\\OpenAI\\Codex\\bin\\&lt;一串哈希&gt;\\codex.exe</code>，哈希随版本变，别写死：</p><div class="language-powershell" data-highlighter="shiki" data-ext="powershell" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-powershell"><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-Process</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Where-Object</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$_</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.Path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-like</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;*odex*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Select-Object</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Unique</span></span></code></pre></div><p>取 <code>Path</code> 的目录部分，临时加进 PATH：</p><div class="language-powershell" data-highlighter="shiki" data-ext="powershell" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-powershell"><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;;C:\\Users\\&lt;用户名&gt;\\AppData\\Local\\OpenAI\\Codex\\bin\\&lt;哈希&gt;&quot;</span></span></code></pre></div><h3 id="三步验证" tabindex="-1"><a class="header-anchor" href="#三步验证"><span>三步验证</span></a></h3><div class="language-powershell" data-highlighter="shiki" data-ext="powershell" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-powershell"><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1) 配置自检：期望 opencode-go，且不应出现 &quot;ignored&quot; 字样</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">codex doctor </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Select-String</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Pattern </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;provider&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;model&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ignored&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2) 端到端发一次真请求：期望 provider: opencode-go + 结尾 OK</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">codex exec </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">skip-git</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">repo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">check </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;reply with the single word OK&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3) 换模型也通</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">codex exec </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">skip-git</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">repo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">check </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c model</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&quot;deepseek-v4-pro&quot;&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;say OK&quot;</span></span></code></pre></div><div class="hint-container important"><p class="hint-container-title">重要</p><p><strong>验证必须用 <code>codex exec</code></strong>，实测 <code>codex debug models</code> 校验更宽松（14 个字段它也放行），看不出一部分 <code>missing field</code> 错误。</p></div><h3 id="生效需要完全重启-app" tabindex="-1"><a class="header-anchor" href="#生效需要完全重启-app"><span>生效需要完全重启 app</span></a></h3><p>配置只在 app 启动时读一次，且 app 是<strong>按「线程创建时」定 provider</strong> 的：</p><div class="language-powershell" data-highlighter="shiki" data-ext="powershell" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-powershell"><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-Process</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ChatGPT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Codex </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ErrorAction SilentlyContinue </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Stop-Process</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Force</span></span></code></pre></div><p><code>-Force</code> 的官方含义只是「不再询问确认」，自己启动的进程本来就不会问，可省。这是硬杀，app 里正在跑的任务会丢；温柔点就用托盘右键退出。重启后<strong>新开任务</strong>。</p><h3 id="使用注意" tabindex="-1"><a class="header-anchor" href="#使用注意"><span>使用注意</span></a></h3><ul><li><p><strong>别在 app 的模型选择器里手动切模型</strong>：选择器不认 provider，只改模型名不改 provider，会直接把会话打坏，报 <code>the model is not supported when using Codex with a ChatGPT account</code>。模型由 <code>config.toml</code> 的 <code>model</code> 决定。</p></li><li><p>项目级 <code>.codex/config.toml</code> 只能改 <code>model</code>，<strong>不能改 provider</strong>（官方限制：provider 设置只能放用户级）。</p></li><li><p>终端直接干活要给沙箱权限，默认 <code>read-only</code>：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sandbox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workspace-write</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;...&quot;</span></span></code></pre></div></li></ul><h2 id="六、排障对照表" tabindex="-1"><a class="header-anchor" href="#六、排障对照表"><span>六、排障对照表</span></a></h2><table><thead><tr><th>报错 / 现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td><code>401 Incorrect API key provided</code> / <code>failed to connect to websocket: 401</code>，url 是 <code>api.openai.com</code>（或 <code>wss://api.openai.com/v1/responses</code>）</td><td>provider 仍是内置 <code>openai</code>：要么顶层键不在文件最前面，要么 <code>model_provider</code> 漏写 / 被覆盖（加 <code>model_catalog_json</code> 时最容易发生，配置不报错）</td><td>确认 <code>model</code> / <code>model_provider</code> / <code>model_catalog_json</code> 三行都在最前面；<code>codex logout</code> 清掉用 Go key 做的登录；用 <code>codex exec</code> 验 <code>provider: opencode-go</code></td></tr><tr><td><code>codex doctor</code> 显示 <code>model_providers.opencode-go.notify is ignored</code></td><td><code>[model_providers...]</code> 表插到了顶层键前面</td><td>顶层键在上、表在下，provider 表放文件末尾</td></tr><tr><td><code>401 Missing API key</code>（打 <code>opencode.ai</code>）</td><td>认证方式用反了</td><td>Go 的 OpenAI 侧（含 <code>/responses</code>）= Bearer；<code>x-api-key</code> 是 <code>/v1/messages</code> 的用法</td></tr><tr><td><code>Error loading config.toml: wire_api = &quot;chat&quot; is no longer supported</code></td><td>Codex 已移除 chat 支持</td><td>改成 <code>wire_api = &quot;responses&quot;</code></td></tr><tr><td><code>Model not supported for format openai</code> / <code>500 Internal server error</code></td><td>该模型没在 <code>/responses</code> 上暴露</td><td>查「二、能用的模型」换模型，或加本地转换代理</td></tr><tr><td><code>422 Upstream request failed</code>（<code>grok-4.6</code>）</td><td>该模型在 <code>/responses</code> 上跑不了 Codex 的真实负载</td><td>换模型</td></tr><tr><td><code>failed to parse model_catalog_json ... missing field &#39;xxx&#39;</code></td><td>目录文件字段不全</td><td>缺什么补什么，优先照 DeepSeek 官方 <code>models.json</code> 的字段与取值；<code>base_instructions</code> 常被漏</td></tr><tr><td>工具调用输出 <code>&lt;|DSML| invoke ...&gt;</code> 纯文本、文件建不出来</td><td>目录条目继承了 GPT 模板的 <code>tool_mode: &quot;code_mode_only&quot;</code> / <code>use_responses_lite: true</code></td><td>改成官方值 <code>tool_mode: null</code>、<code>use_responses_lite: false</code>（别的字段照官方保留，<code>apply_patch_tool_type: &quot;freeform&quot;</code> 没问题）</td></tr><tr><td><code>cannot be used while config.toml contains legacy [profiles.x] config</code></td><td>用了老式 profile 写法</td><td>挪到独立的 <code>&lt;名字&gt;.config.toml</code> 文件</td></tr><tr><td><code>codex</code> 不是可识别的命令</td><td>app 自带 CLI 不在 PATH</td><td>按「五、」第一步找真实路径，或 <code>npm i -g @openai/codex</code> 装一份稳定 CLI</td></tr><tr><td>app 里推理档位只剩两档（少了中间那档）</td><td>目录里写了客户端渲染不出来的档位（如官方 DeepSeek 目录的 <code>max</code>）——客户端只认 <code>minimal|low|medium|high|xhigh</code></td><td>把 <code>supported_reasoning_levels</code> 改成 <code>low</code> / <code>medium</code> / <code>high</code>，默认 <code>default_reasoning_level = &quot;high&quot;</code></td></tr><tr><td>app 里模型名显示「自定义 / 轻度」</td><td>内置目录里没有该 slug</td><td>加 <code>model_catalog_json</code>（注意是整体替换），或只设 <code>model_reasoning_effort</code></td></tr><tr><td>app 里手动选模型后报 <code>model is not supported ... ChatGPT account</code></td><td>选择器不认 provider</td><td>别手动切；必要时用官方 ChatGPT 账号登录一次让门禁放行</td></tr></tbody></table><h2 id="结语" tabindex="-1"><a class="header-anchor" href="#结语"><span>结语</span></a></h2><p>整件事的关键只有三点：<code>wire_api</code> 必须是 <code>responses</code>、认证走 Bearer、顶层键必须在所有表头之前。模型选择上，六个可用模型里对 Codex 最省事的是 <code>deepseek-v4.1-flash</code> 与 <code>deepseek-v4-pro</code>；如果只需要一个能跑通的默认项，<code>deepseek-v4.1-flash</code> 足够。</p><p>参考来源：</p><ul><li>DeepSeek 官方 Codex 接入文档（含官方 <code>models.json</code> 完整内容）：<code>https://api-docs.deepseek.com/zh-cn/quick_start/agent_integrations/codex</code></li><li>Codex 配置参考：<code>https://developers.openai.com/codex/config-reference</code></li></ul>`,70)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};